#include "mmx_boss_rush_foreign.h"
#include "mmx_boss_rush.h"
#include "mmx_cart_extension.h"
#include "mmx_boss_rush_audio.h"
#include <stdio.h>
#include <string.h>

/* Relocation descriptors generated by tools/relocate_boss.py. They hold only
 * addresses and the original operand values used to verify the source ROM;
 * code and data are copied from the user's ROM here, in memory. */
typedef struct MmxRelocBank {uint8_t source,dest;} MmxRelocBank;
typedef struct MmxRelocCopy {uint32_t source,dest;uint16_t size;} MmxRelocCopy;
typedef struct MmxRelocBlob {uint32_t at;uint16_t offset,size;} MmxRelocBlob;
typedef struct MmxRelocPatch {uint32_t at;uint8_t size;uint32_t expected,value;} MmxRelocPatch;
typedef struct MmxRelocChild {uint8_t kind;uint32_t controller;} MmxRelocChild;
#include "mmx_boss_rush_x3_rhino.inc"

typedef struct MmxRelocBoss {
  const char *name;
  unsigned game,roster_id;
  uint32_t body;
  uint8_t fighting,dying;
  const MmxRelocBank *banks;size_t bank_count;
  const MmxRelocCopy *copies;size_t copy_count;
  const uint8_t *code;
  const MmxRelocBlob *blobs;size_t blob_count;
  const MmxRelocPatch *patches;size_t patch_count;
  const MmxRelocChild *children;size_t child_count;
  unsigned sound_bank;uint32_t sfx,sfx_pan;
  const uint8_t *effects;size_t effect_count;
  const MmxBossRushWeakness *weaknesses;size_t weakness_count;
} MmxRelocBoss;
#define COUNT(a) (sizeof(a)/sizeof(*(a)))
/* X1 shot classes: Homing Torpedo $0E, Shotgun Ice $07; charged +9. */
enum { X1_ICE=0x07, X1_TORPEDO=0x0e, CHARGED=9 };
/* Rhino runs on Kuwanger's X1 row, whose weakness column is Homing Torpedo's.
 * His original X3 weakness, Acid Burst, takes that column and reports the
 * Torpedo reaction his relocated flinch test looks for. Homing Torpedo
 * itself is moved to an ordinary column (Ice) so it is not a weakness.
 * Extra X1/X2 weaknesses are assigned once all 24 bosses exist. */
static const MmxBossRushWeakness k_rhino_weaknesses[]={
  {2,1,{X1_TORPEDO,X1_TORPEDO+CHARGED},{X1_TORPEDO,X1_TORPEDO+CHARGED}}, /* X3 Acid Burst */
  {0,1,{X1_ICE,X1_ICE+CHARGED},{X1_ICE,X1_ICE+CHARGED}},                 /* X1 Homing Torpedo */
};
static const MmxRelocBoss kBosses[]={
  {"TUNNEL RHINO",3,k_rhino_roster_id,k_rhino_body,2,4,
   k_rhino_banks,COUNT(k_rhino_banks),k_rhino_copies,COUNT(k_rhino_copies),
   k_rhino_shim_code,k_rhino_blobs,COUNT(k_rhino_blobs),
   k_rhino_patches,COUNT(k_rhino_patches),k_rhino_children,COUNT(k_rhino_children),
   k_rhino_sound_bank,k_rhino_sfx,k_rhino_sfx_pan,k_rhino_effects,COUNT(k_rhino_effects),
   k_rhino_weaknesses,COUNT(k_rhino_weaknesses)},
};
/* Zero/sink area for X3-only globals: reads see zero, writes hit ROM. */
enum { ZERO_AREA=0x86fe00, ZERO_SIZE=0x200 };

static bool source(const uint8_t *rom,size_t size,uint32_t address,size_t n,const uint8_t **out) {
  if((address&0xffff)<0x8000) return false;
  size_t at=((size_t)((address>>16)&0x7f)<<15)|(address&0x7fff);
  if(at>size || n>size-at) return false;
  *out=rom+at;return true;
}
static bool build(const MmxRelocBoss *boss,const uint8_t *rom,size_t size,char *error,size_t cap) {
  for(size_t i=0;i<boss->bank_count;++i) {
    const uint8_t *bytes;
    if(!source(rom,size,(uint32_t)boss->banks[i].source<<16|0x8000,0x8000,&bytes) ||
        !MmxCartExtensionWrite((uint32_t)boss->banks[i].dest<<16|0x8000,bytes,0x8000)) {
      snprintf(error,cap,"%s: cannot copy bank $%02X",boss->name,boss->banks[i].source);return false;
    }
  }
  /* Shims first: copies fill the class-init shim's immediates. */
  for(size_t i=0;i<boss->blob_count;++i) {
    const MmxRelocBlob *b=&boss->blobs[i];
    if(!MmxCartExtensionWrite(b->at,boss->code+b->offset,b->size)) {
      snprintf(error,cap,"%s: cannot place shim $%06X",boss->name,b->at);return false;
    }
  }
  for(size_t i=0;i<boss->copy_count;++i) {
    const uint8_t *bytes;const MmxRelocCopy *c=&boss->copies[i];
    if(!source(rom,size,c->source,c->size,&bytes) || !MmxCartExtensionWrite(c->dest,bytes,c->size)) {
      snprintf(error,cap,"%s: cannot copy $%06X",boss->name,c->source);return false;
    }
  }
  static const uint8_t zero[ZERO_SIZE];
  if(!MmxCartExtensionWrite(ZERO_AREA,zero,sizeof(zero))) {
    snprintf(error,cap,"%s: cannot reserve the zero area",boss->name);return false;
  }
  for(size_t i=0;i<boss->patch_count;++i) {
    const MmxRelocPatch *p=&boss->patches[i];
    uint8_t now[3]={0},value[3]={(uint8_t)p->value,(uint8_t)(p->value>>8),(uint8_t)(p->value>>16)};
    uint32_t found=0;
    if(p->size<1 || p->size>3 || !MmxCartExtensionRead(p->at,now,p->size)) {
      snprintf(error,cap,"%s: invalid patch $%06X",boss->name,p->at);return false;
    }
    for(unsigned k=0;k<p->size;++k) found|=(uint32_t)now[k]<<(8*k);
    /* The source ROM must hold the traced operand before it is rewritten. */
    if(found!=p->expected || !MmxCartExtensionWrite(p->at,value,p->size)) {
      snprintf(error,cap,"%s: unexpected operand at $%06X",boss->name,p->at);return false;
    }
  }
  if(!MmxBossRushForeignSetController(boss->roster_id,boss->body) ||
      !MmxBossRushForeignSetStates(boss->roster_id,boss->fighting,boss->dying)) {
    snprintf(error,cap,"%s: cannot register its body",boss->name);return false;
  }
  for(size_t i=0;i<boss->child_count;++i)
    if(!MmxBossRushForeignSetChild(boss->roster_id,boss->children[i].kind,boss->children[i].controller)) {
      snprintf(error,cap,"%s: cannot register projectile $%02X",boss->name,boss->children[i].kind);return false;
    }
  /* Its X3 sound calls are hooked shims; render those effects from its own
   * driver and sound bank. A failed cache leaves the boss silent. */
  if(!MmxBossRushForeignSetWeaknesses(boss->roster_id,boss->weaknesses,(unsigned)boss->weakness_count)) {
    snprintf(error,cap,"%s: cannot register its weaknesses",boss->name);return false;
  }
  MmxBossRushForeignSetSoundShims(boss->sfx,boss->sfx_pan);
  MmxBossRushAudioPrepareForeign(boss->roster_id,rom,size,boss->sound_bank,boss->effects,(unsigned)boss->effect_count);
  return true;
}
bool MmxBossRushForeignBuild(char *error,size_t cap) {
  for(size_t i=0;i<COUNT(kBosses);++i) MmxBossRushForeignSetController(kBosses[i].roster_id,0);
  MmxBossRushForeignSetSoundShims(0,0);
  MmxCartExtensionClear();
  if(!MmxCartPatchAvailable()) {
    snprintf(error,cap,"The loaded Mega Man X image cannot host relocated bosses.");return false;
  }
  for(size_t i=0;i<COUNT(kBosses);++i) {
    size_t size=0;const uint8_t *rom=MmxBossRushForeignRom(kBosses[i].game,&size);
    if(!rom) {MmxBossRushAudioPrepareForeign(kBosses[i].roster_id,NULL,0,0,NULL,0);continue;}
    if(!build(&kBosses[i],rom,size,error,cap)) {
      MmxBossRushForeignSetController(kBosses[i].roster_id,0);MmxCartExtensionClear();
      return false;
    }
  }
  if(error && cap) error[0]=0;
  return true;
}
